/**
 * Stub of `@deepseek-ai/cordis` — only the surface the doctor touches.
 *
 * `Service` just records its context and service name; `Service.Config` exists
 * because shipped plugins declare `static Config = Schema.object(...)`.
 */
export class Service {
  constructor(ctx, name) {
    this.ctx = ctx;
    this.name = name;
  }
}

Service.Config = {};

export class Context {
  constructor(ctx) {
    this.ctx = ctx;
  }
}

export default { Service, Context };
